function generateParenthesis(n) { // 1
    const result = []; // 2

    function backtrack(current_string, open_count, close_count) { // 3
        // Base case: If we have n open and n close parentheses, a valid combination is found.
        if (open_count === n && close_count === n) { // 4
            result.push(current_string); // 5
            return; // 6
        }

        // Option 1: Add an open parenthesis if we haven't used all n yet.
        if (open_count < n) { // 7
            backtrack(current_string + "(", open_count + 1, close_count); // 8
        }

        // Option 2: Add a close parenthesis if it doesn't violate well-formedness.
        // (i.e., we have more open parentheses than close ones currently).
        if (close_count < open_count) { // 9
            backtrack(current_string + ")", open_count, close_count + 1); // 10
        }
    }

    backtrack("", 0, 0); // 11
    return result; // 12
}
